const PT_GRAMMAR_SKILLS = [
  { id:'pt_ser_estar', unit:'pt-core-1', icon:'🪞', title:'ser vs estar — the two "to be"s',
    explain:'Portuguese splits "to be" in two. <b>ser</b> is for what something IS — identity, origin, profession, permanent qualities. <b>estar</b> is for how something IS right now — feelings, locations, temporary states.',
    examples:[['Sou de Cabo Verde.','I am from Cape Verde. (origin → ser)'],['Estou cansado.','I am tired. (state → estar)'],['A comida está fria.','The food is cold. (right now → estar)']],
    qs:[
      { q:'"I am a teacher" is:', opts:['Sou professor','Estou professor','Tenho professor','Vou professor'], a:0, why:'A profession is identity → ser.' },
      { q:'"She is tired" is:', opts:['Ela está cansada','Ela é cansada','Ela tem cansada','Ela vai cansada'], a:0, why:'A temporary state → estar.' },
      { q:'"The house is big" is:', opts:['A casa é grande','A casa está grande','A casa tem grande','A casa vai grande'], a:0, why:'A permanent quality → ser.' },
      { q:'"Where are you?" is:', opts:['Onde estás?','Onde és?','Onde tens?','Onde vais?'], a:0, why:'Location → estar.' },
      { q:'"I am from Lisbon" uses:', opts:['ser','estar','ter','ir'], a:0, why:'Origin is identity → sou de Lisboa.' },
      { q:'"O café está frio" tells you the coffee is:', opts:['cold right now','always cold','a cold type','not coffee'], a:0, why:'estar signals a current, changeable state.' },
    ]},
  { id:'pt_articles', unit:'pt-core-1', icon:'🔠', title:'o, a, um, uma — gender',
    explain:'Every Portuguese noun is masculine or feminine. <b>o</b> / <b>os</b> = the (masc.), <b>a</b> / <b>as</b> = the (fem.). <b>um</b> = a (masc.), <b>uma</b> = a (fem.). Most words ending in <b>-o</b> are masculine and most ending in <b>-a</b> are feminine — but always learn the article with the noun.',
    examples:[['o livro / a casa','the book / the house'],['um café, se faz favor','a coffee, please'],['as minhas irmãs','my sisters']],
    qs:[
      { q:'"The house" is:', opts:['a casa','o casa','um casa','as casa'], a:0, why:'casa is feminine → a casa.' },
      { q:'"A coffee" is:', opts:['um café','uma café','o café','a café'], a:0, why:'café is masculine → um café.' },
      { q:'"The books" is:', opts:['os livros','as livros','o livros','um livros'], a:0, why:'Masculine plural → os.' },
      { q:'Which article goes with "água"?', opts:['a','o','um','os'], a:0, why:'água is feminine → a água.' },
      { q:'Most nouns ending in -a are:', opts:['feminine','masculine','plural','verbs'], a:0, why:'A useful rule of thumb — but learn the article with each noun.' },
      { q:'"The sisters" is:', opts:['as irmãs','os irmãs','a irmãs','um irmãs'], a:0, why:'Feminine plural → as.' },
    ]},
  { id:'pt_present', unit:'pt-core-2', icon:'🔁', title:'The present tense',
    explain:'Portuguese verbs change their ending for each person. Three families: <b>-ar</b> (falar), <b>-er</b> (comer), <b>-ir</b> (partir). For <i>falar</i>: eu fal<b>o</b>, tu fal<b>as</b>, ele fal<b>a</b>, nós fal<b>amos</b>, eles fal<b>am</b>.',
    examples:[['Eu falo português.','I speak Portuguese.'],['Nós comemos às oito.','We eat at eight.'],['Eles partem amanhã.','They leave tomorrow.']],
    qs:[
      { q:'"I speak" is:', opts:['falo','falas','fala','falamos'], a:0, why:'eu → -o: falo.' },
      { q:'"We eat" is:', opts:['comemos','como','comes','comem'], a:0, why:'nós → -emos for -er verbs.' },
      { q:'"She works" is:', opts:['ela trabalha','ela trabalho','ela trabalhas','ela trabalham'], a:0, why:'ele/ela → -a for -ar verbs.' },
      { q:'"You (tu) live" — morar:', opts:['moras','moro','mora','moramos'], a:0, why:'tu → -as.' },
      { q:'The three verb families end in:', opts:['-ar, -er, -ir','-o, -a, -e','-ão, -am, -em','-ar, -or, -ur'], a:0, why:'Every infinitive ends -ar, -er or -ir.' },
      { q:'"They learn" is:', opts:['aprendem','aprendo','aprende','aprendemos'], a:0, why:'eles → -em for -er verbs.' },
    ]},
  { id:'pt_agreement', unit:'pt-core-2', icon:'🧮', title:'Plurals & agreement',
    explain:'Adjectives copy the gender and number of the noun. <i>um carro branc<b>o</b></i> → <i>duas casas branc<b>as</b></i>. Most plurals just add <b>-s</b>; words ending in <b>-ão</b> often become <b>-ões</b>, and <b>-l</b> becomes <b>-is</b>.',
    examples:[['o menino alto / a menina alta','the tall boy / the tall girl'],['dois pães','two loaves'],['os hotéis são caros','the hotels are expensive']],
    qs:[
      { q:'"The tall girl" is:', opts:['a menina alta','a menina alto','o menina alta','a menina altos'], a:0, why:'The adjective matches feminine singular: alta.' },
      { q:'Plural of "pão" is:', opts:['pães','pãos','pão','pães-es'], a:0, why:'-ão often becomes -ães or -ões; pão → pães.' },
      { q:'"The houses are white" is:', opts:['As casas são brancas','As casas são branco','A casas são brancas','As casa são brancas'], a:0, why:'Everything goes feminine plural.' },
      { q:'Plural of "hotel" is:', opts:['hotéis','hotels','hoteles','hotelis'], a:0, why:'Words in -l take -is: hotel → hotéis.' },
      { q:'Adjectives in Portuguese:', opts:['agree with the noun','never change','always end in -o','come first'], a:0, why:'They copy gender and number.' },
      { q:'"Two expensive tickets" is:', opts:['dois bilhetes caros','dois bilhete caro','duas bilhetes caras','dois bilhetes caro'], a:0, why:'Masculine plural throughout: dois bilhetes caros.' },
    ]},
  { id:'pt_future', unit:'pt-core-3', icon:'⏩', title:'The easy future: ir + infinitive',
    explain:'The everyday future needs no new endings: conjugate <b>ir</b> (vou, vais, vai, vamos, vão) and add the plain infinitive. <i>Vou comer</i> = I am going to eat. There is a formal one-word future (<i>comerei</i>), but speakers use ir + infinitive constantly.',
    examples:[['Vou trabalhar amanhã.','I am going to work tomorrow.'],['Vamos comer fora.','We are going to eat out.'],['Eles vão chegar tarde.','They are going to arrive late.']],
    qs:[
      { q:'"I am going to travel" is:', opts:['Vou viajar','Vais viajar','Vamos viajar','Vou viajo'], a:0, why:'eu → vou + infinitive.' },
      { q:'"We are going to eat" is:', opts:['Vamos comer','Vamos comemos','Vou comer','Vão comer'], a:0, why:'nós → vamos + infinitive.' },
      { q:'After ir, the second verb is:', opts:['the plain infinitive','conjugated too','in the past','left out'], a:0, why:'Vou comer — never "vou como".' },
      { q:'"She is going to study" is:', opts:['Ela vai estudar','Ela vais estudar','Ela vão estudar','Ela vai estuda'], a:0, why:'ela → vai + estudar.' },
      { q:'"They are going to leave" is:', opts:['Eles vão partir','Eles vamos partir','Eles vai partir','Eles vão partem'], a:0, why:'eles → vão + infinitive.' },
      { q:'Which is wrong?', opts:['Vou como','Vou comer','Vais comer','Vamos comer'], a:0, why:'Never conjugate the second verb after ir.' },
    ]},
  { id:'pt_contractions', unit:'pt-core-5', icon:'🔗', title:'Contractions: do, na, ao, pelo',
    explain:'Portuguese fuses prepositions with articles, and it is compulsory. <b>de</b>+o=<b>do</b>, de+a=<b>da</b>; <b>em</b>+o=<b>no</b>, em+a=<b>na</b>; <b>a</b>+o=<b>ao</b>, a+a=<b>à</b>; <b>por</b>+o=<b>pelo</b>.',
    examples:[['Vou ao mercado.','I am going to the market. (a + o)'],['Está na cozinha.','It is in the kitchen. (em + a)'],['A casa do meu pai.','My father\'s house. (de + o)']],
    qs:[
      { q:'"I am going to the beach (a praia)" is:', opts:['Vou à praia','Vou a praia','Vou na praia','Vou da praia'], a:0, why:'a + a = à (with the accent).' },
      { q:'"In the house" is:', opts:['na casa','em casa a','a casa','da casa'], a:0, why:'em + a = na.' },
      { q:'"The book of the boy" is:', opts:['o livro do menino','o livro de o menino','o livro no menino','o livro ao menino'], a:0, why:'de + o = do — never written apart.' },
      { q:'"On the table (a mesa)" is:', opts:['na mesa','no mesa','à mesa de','da mesa'], a:0, why:'em + a = na mesa.' },
      { q:'"I pay for the coffee" — por + o café:', opts:['pelo café','por o café','pro café','pelo o café'], a:0, why:'por + o = pelo.' },
      { q:'Are these contractions optional?', opts:['No, they are compulsory','Yes, in speech only','Only in writing','Only in Brazil'], a:0, why:'"de o" is always wrong — it must be do.' },
    ]},
  { id:'pt_imperfeito', unit:'pt-core-6', icon:'🕰️', title:'Used to & was doing (imperfeito)',
    explain:'The <b>imperfeito</b> paints the background of the past: what you used to do, or what was going on. For -ar: fal<b>ava</b>, fal<b>avas</b>, fal<b>ava</b>, fal<b>ávamos</b>, fal<b>avam</b>. For -er/-ir: com<b>ia</b>, com<b>ias</b>… Three to memorise: <b>era</b> (was), <b>tinha</b> (had), <b>havia</b> (there was).',
    examples:[['Quando era criança, morava em Mindelo.','When I was a child, I used to live in Mindelo.'],['Ela cantava enquanto cozinhava.','She was singing while she cooked.'],['Não havia electricidade.','There was no electricity.']],
    qs:[
      { q:'"I used to work there" is:', opts:['Trabalhava lá','Trabalhei lá','Vou trabalhar lá','Trabalho lá'], a:0, why:'A repeated past habit → imperfeito: trabalhava.' },
      { q:'"When I was a child" is:', opts:['Quando era criança','Quando fui criança','Quando sou criança','Quando serei criança'], a:0, why:'era is the imperfeito of ser — a background state.' },
      { q:'Which sentence describes an ongoing scene?', opts:['Ela cantava enquanto cozinhava','Ela cantou uma canção','Ela vai cantar','Ela tinha cantado'], a:0, why:'imperfeito sets the scene; perfeito reports a finished act.' },
      { q:'"We had a house there" is:', opts:['Tínhamos uma casa lá','Tivemos uma casa lá','Temos uma casa lá','Teremos uma casa lá'], a:0, why:'tinha/tínhamos = the background "had".' },
      { q:'Comi vs comia — "comia" means:', opts:['I used to eat','I ate (once)','I will eat','I have eaten'], a:0, why:'-ia endings give the habitual past.' },
      { q:'"There was no water" is:', opts:['Não havia água','Não houve água','Não há água','Não haverá água'], a:0, why:'havia is the imperfeito of há — the past backdrop.' },
    ]},
  { id:'pt_object_pron', unit:'pt-core-6', icon:'🎯', title:'Object pronouns: -me, -te, -o, -lhe',
    explain:'Direct objects: <b>-me, -te, -o/-a, -nos, -os/-as</b>. Indirect (to someone): <b>-me, -te, -lhe, -nos, -lhes</b>. In Portugal they hook onto the end of the verb with a hyphen — <i>dá-me</i>, <i>vejo-o</i> — but they jump in front after <b>não</b>, question words, and <i>que</i>.',
    examples:[['Dá-me o livro.','Give me the book.'],['Não me dás o livro?','Won\'t you give me the book?'],['Disse-lhe a verdade.','I told him/her the truth.']],
    qs:[
      { q:'"Give me the key" is:', opts:['Dá-me a chave','Dá a chave me','Me dá a chave','Dá-lhe a chave'], a:0, why:'-me hooks onto the verb with a hyphen.' },
      { q:'"I do not know him" is:', opts:['Não o conheço','Não conheço-o','Conheço-o não','Não lhe conheço'], a:0, why:'After não, the pronoun moves BEFORE the verb.' },
      { q:'"I told her" uses:', opts:['-lhe','-a','-o','-me'], a:0, why:'Telling someone is indirect → disse-lhe.' },
      { q:'"He helps us" is:', opts:['Ele ajuda-nos','Ele ajuda-lhes','Ele nos ajuda-','Ele ajuda-os'], a:0, why:'-nos = us, attached to the verb.' },
      { q:'Which triggers the pronoun to move forward?', opts:['não / que / question words','a comma','the future','nothing'], a:0, why:'Negatives, subordinating que and question words pull it in front.' },
      { q:'"I saw them (the books)" is:', opts:['Vi-os','Vi-lhes','Vi-nos','Vi-as'], a:0, why:'Masculine plural direct object → -os.' },
    ]},
  { id:'pt_reflexive', unit:'pt-core-7', icon:'🪞', title:'Reflexive verbs (-se)',
    explain:'Many daily actions are reflexive: the subject does it to itself. <b>levantar-se</b> (to get up), <b>chamar-se</b> (to be called), <b>sentir-se</b> (to feel), <b>lembrar-se</b> (to remember). The pronoun changes with the person: <i>levanto-<b>me</b></i>, <i>levantas-<b>te</b></i>, <i>levanta-<b>se</b></i>.',
    examples:[['Levanto-me às seis.','I get up at six.'],['Como te chamas?','What is your name?'],['Não me sinto bem.','I do not feel well.']],
    qs:[
      { q:'"I get up early" is:', opts:['Levanto-me cedo','Levanto cedo-me','Me levanto cedo','Levanta-se cedo'], a:0, why:'eu → -me, attached after the verb.' },
      { q:'"What is your name?" (tu) is:', opts:['Como te chamas?','Como se chama tu?','Como me chamo?','Como chamas-te?'], a:0, why:'A question word pulls the pronoun forward: como te chamas.' },
      { q:'"He feels tired" is:', opts:['Ele sente-se cansado','Ele sente cansado','Ele se sente cansado','Ele sentir-se cansado'], a:0, why:'ele → -se.' },
      { q:'"I forgot" is:', opts:['Esqueci-me','Esqueci-se','Esquece-me','Me esqueci'], a:0, why:'esquecer-se, eu form → esqueci-me.' },
      { q:'"We remember" is:', opts:['Lembramo-nos','Lembramos-nos','Lembra-nos','Nos lembramos'], a:0, why:'The -s drops before -nos: lembramo-nos.' },
      { q:'A reflexive verb means the action:', opts:['returns to the subject','is in the past','is negative','is formal'], a:0, why:'You do it to yourself: I wash myself, I call myself.' },
    ]},
  { id:'pt_compare', unit:'pt-core-8', icon:'⚖️', title:'Comparing & superlatives',
    explain:'<b>mais … do que</b> (more than), <b>menos … do que</b> (less than), <b>tão … como</b> (as … as). Irregulars: <b>melhor</b> (better), <b>pior</b> (worse), <b>maior</b> (bigger), <b>menor</b> (smaller). For "the most", add the article: <b>o mais caro</b>. And <b>-íssimo</b> means extremely: <i>caríssimo</i>.',
    examples:[['Este é mais caro do que aquele.','This is more expensive than that one.'],['Ela é tão alta como o irmão.','She is as tall as her brother.'],['É o melhor restaurante da cidade.','It is the best restaurant in the city.']],
    qs:[
      { q:'"Cheaper than this" is:', opts:['mais barato do que este','mais barato que de este','menos barato como este','o mais barato este'], a:0, why:'mais + adjective + do que.' },
      { q:'"Better" is:', opts:['melhor','mais bom','mais melhor','bom mais'], a:0, why:'melhor is irregular — never "mais bom".' },
      { q:'"As tall as me" is:', opts:['tão alto como eu','mais alto como eu','tão alto do que eu','alto como mais eu'], a:0, why:'tão … como for equality.' },
      { q:'"The most beautiful island" is:', opts:['a ilha mais bonita','a mais ilha bonita','mais a ilha bonita','a ilha muito bonita'], a:0, why:'Article + noun + mais + adjective.' },
      { q:'"caríssimo" means:', opts:['extremely expensive','a bit expensive','cheap','the cheapest'], a:0, why:'-íssimo is the absolute superlative.' },
      { q:'"Worse than yesterday" is:', opts:['pior do que ontem','mais mau do que ontem','menos bom ontem','pior como ontem'], a:0, why:'pior is the irregular comparative of mau.' },
    ]},
  { id:'pt_futuro_cond', unit:'pt-core-9', icon:'🔮', title:'Futuro & condicional',
    explain:'Beyond <i>ir</i> + infinitive there are two one-word tenses, built by adding endings to the whole infinitive. Future: falar<b>ei</b>, falar<b>ás</b>, falar<b>á</b>, falar<b>emos</b>, falar<b>ão</b>. Conditional (<i>would</i>): falar<b>ia</b>, falar<b>ias</b>… <b>Gostaria</b> (I would like) is the politest word in the language.',
    examples:[['Amanhã falarei com ele.','Tomorrow I will speak with him.'],['Gostaria de reservar uma mesa.','I would like to book a table.'],['Nesse caso, seria melhor esperar.','In that case, it would be better to wait.']],
    qs:[
      { q:'"I would like a coffee" (polite) is:', opts:['Gostaria de um café','Gosto de um café','Gostei de um café','Gostarei de um café'], a:0, why:'The conditional gostaria is the polite request form.' },
      { q:'"They will arrive tomorrow" is:', opts:['Chegarão amanhã','Chegaram amanhã','Chegariam amanhã','Chegavam amanhã'], a:0, why:'-ão is the future ending for eles.' },
      { q:'The conditional endings are:', opts:['-ia, -ias, -ia, -íamos, -iam','-ei, -ás, -á','-ava, -avas','-e, -es, -e'], a:0, why:'Infinitive + -ia gives "would".' },
      { q:'"It would be better" is:', opts:['Seria melhor','Será melhor','Foi melhor','Era melhor sido'], a:0, why:'seria = would be.' },
      { q:'Future and conditional endings attach to:', opts:['the whole infinitive','the stem only','the past form','the participle'], a:0, why:'falar + ei, falar + ia — the infinitive stays whole.' },
      { q:'Which sounds most polite in a shop?', opts:['Queria / Gostaria de…','Quero…','Dá-me…','Vou levar'], a:0, why:'The conditional softens a request considerably.' },
    ]},
  { id:'pt_subjunctive', unit:'pt-core-10', icon:'🌙', title:'The subjunctive (conjuntivo)',
    explain:'Portuguese uses a special mood for things that are wished, doubted or not yet real. Trigger phrases: <b>espero que</b>, <b>quero que</b>, <b>talvez</b>, <b>é possível que</b>, <b>embora</b>. Forms flip the vowel: falar → que eu <b>fale</b>; comer → que eu <b>coma</b>.',
    examples:[['Espero que estejas bem.','I hope you are well.'],['Talvez ele venha amanhã.','Perhaps he will come tomorrow.'],['Quero que me digas a verdade.','I want you to tell me the truth.']],
    qs:[
      { q:'"I hope you are well" is:', opts:['Espero que estejas bem','Espero que estás bem','Espero que estarás bem','Espero que estavas bem'], a:0, why:'espero que triggers the subjunctive: estejas.' },
      { q:'Which word triggers the subjunctive?', opts:['talvez','ontem','sempre','muito'], a:0, why:'talvez (perhaps) marks something unreal or uncertain.' },
      { q:'"I want you to come" is:', opts:['Quero que venhas','Quero que vens','Quero que virás','Quero vir'], a:0, why:'Wanting someone else to act → que + subjunctive.' },
      { q:'For -ar verbs the subjunctive vowel becomes:', opts:['-e (fale)','-a (fala)','-i (fali)','-o (falo)'], a:0, why:'-ar verbs flip to -e; -er/-ir verbs flip to -a.' },
      { q:'"Even though it is expensive" is:', opts:['Embora seja caro','Embora é caro','Embora era caro','Embora foi caro'], a:0, why:'embora always takes the subjunctive.' },
      { q:'The subjunctive is used for things that are:', opts:['wished, doubted or unreal','always true','finished','habitual'], a:0, why:'It is the mood of hope, doubt and possibility.' },
    ]},
  { id:'pt_relatives', unit:'pt-core-11', icon:'🪢', title:'Relative pronouns: que, quem, cujo',
    explain:'<b>que</b> is the workhorse — it covers who, which and that. Use <b>quem</b> only after a preposition and only for people (<i>a pessoa com quem falei</i>). <b>cujo/cuja</b> means whose and agrees with the thing owned. <b>o qual</b> is the formal alternative that avoids ambiguity.',
    examples:[['O livro que comprei é caro.','The book that I bought is expensive.'],['A pessoa com quem falei era simpática.','The person I spoke with was kind.'],['O escritor cuja obra estudámos nasceu aqui.','The writer whose work we studied was born here.']],
    qs:[
      { q:'"The house that I bought" is:', opts:['A casa que comprei','A casa quem comprei','A casa cuja comprei','A casa qual comprei'], a:0, why:'que covers that / which / who in most cases.' },
      { q:'"The friend with whom I travelled" is:', opts:['O amigo com quem viajei','O amigo com que viajei','O amigo cujo viajei','O amigo quem viajei'], a:0, why:'After a preposition, people take quem.' },
      { q:'"The man whose car broke down" is:', opts:['O homem cujo carro se avariou','O homem que carro se avariou','O homem quem carro','O homem de que carro'], a:0, why:'cujo = whose, and agrees with carro (masculine).' },
      { q:'cujo agrees with:', opts:['the thing owned','the owner','the verb','nothing'], a:0, why:'cuja casa, cujo carro — it matches what is possessed.' },
      { q:'"The reasons for which he left" (formal) is:', opts:['As razões pelas quais saiu','As razões que saiu','As razões quem saiu','As razões cujas saiu'], a:0, why:'o qual / as quais is the formal option after prepositions.' },
      { q:'Which is wrong: "A mulher que mora ali"?', opts:['It is correct','Should be quem','Should be cuja','Should be a qual only'], a:0, why:'que is perfectly correct for a subject relative, person or thing.' },
    ]},
  { id:'pt_compound', unit:'pt-core-12', icon:'⏱️', title:'Compound tenses: tenho feito, tinha feito',
    explain:'Portuguese builds compound tenses with <b>ter</b> + past participle. <b>Tenho feito</b> means something repeated up to now (not simply "I have done"). <b>Tinha feito</b> is the pluperfect — done before another past moment. Watch the irregular participles: feito, dito, visto, posto, escrito, aberto.',
    examples:[['Tenho trabalhado muito ultimamente.','I have been working a lot lately.'],['Quando cheguei, ela já tinha saído.','When I arrived, she had already left.'],['Tinha escrito a carta antes de partir.','I had written the letter before leaving.']],
    qs:[
      { q:'"I have been studying a lot lately" is:', opts:['Tenho estudado muito','Estudei muito','Tinha estudado muito','Estudarei muito'], a:0, why:'tenho + participle = repeated action continuing up to now.' },
      { q:'"She had already left" is:', opts:['Ela já tinha saído','Ela já saiu','Ela já tem saído','Ela já sairá'], a:0, why:'tinha + participle = the pluperfect, before another past event.' },
      { q:'The participle of "fazer" is:', opts:['feito','fazido','fez','fazendo'], a:0, why:'fazer → feito, one of the common irregulars.' },
      { q:'The participle of "ver" is:', opts:['visto','vido','viu','vendo'], a:0, why:'ver → visto.' },
      { q:'"Tenho ido ao ginásio" means:', opts:['I have been going regularly','I went once','I will go','I had gone'], a:0, why:'The Portuguese present perfect implies repetition up to now.' },
      { q:'Compound tenses are built with:', opts:['ter + past participle','ser + gerund','ir + infinitive','estar + infinitive'], a:0, why:'ter is the auxiliary — haver only in very formal writing.' },
    ]},
  { id:'pt_passive', unit:'pt-core-12', icon:'🔄', title:'Passive & impersonal se',
    explain:'The true passive uses <b>ser</b> + participle, which agrees: <i>A casa foi construída em 1950</i>. Far more common in speech is the impersonal <b>se</b>: <i>Fala-se português aqui</i> (Portuguese is spoken here), <i>Vendem-se casas</i> (houses for sale) — note the verb agrees with the thing.',
    examples:[['A ponte foi construída em 1966.','The bridge was built in 1966.'],['Aqui fala-se crioulo e português.','Creole and Portuguese are spoken here.'],['Vendem-se apartamentos.','Apartments for sale.']],
    qs:[
      { q:'"The house was built in 1950" is:', opts:['A casa foi construída em 1950','A casa construiu em 1950','A casa tem construído','A casa era construir'], a:0, why:'ser + participle, agreeing with casa (feminine).' },
      { q:'"Portuguese is spoken here" is:', opts:['Fala-se português aqui','Fala português aqui','É falado aqui português se','Se fala-se português'], a:0, why:'The impersonal se is the everyday passive.' },
      { q:'"Houses are sold" (sign) is:', opts:['Vendem-se casas','Vende-se casas','Vendem casas se','Casas se vende'], a:0, why:'The verb agrees with casas → vendem-se.' },
      { q:'In the true passive, the participle:', opts:['agrees with the subject','never changes','takes -ndo','follows ter'], a:0, why:'foi construída / foram construídos.' },
      { q:'"It is said that…" is:', opts:['Diz-se que…','Diz que se…','É dito se que','Se diz-se que'], a:0, why:'Diz-se que — the impersonal se with no named agent.' },
      { q:'Which sounds most natural in speech?', opts:['Aqui come-se bem','Aqui é comido bem','Aqui tem comido bem','Aqui foi comer bem'], a:0, why:'Speakers overwhelmingly prefer the impersonal se over the full passive.' },
    ]},
  { id:'pt_se_clauses', unit:'pt-core-11', icon:'🌗', title:'If-clauses & por vs para',
    explain:'Real conditions: <b>Se</b> + present, then future — <i>Se puder, telefono-te</i>. Unreal ones: <b>se</b> + imperfect subjunctive, then conditional — <i>Se tivesse dinheiro, viajaria</i>. And the classic pair: <b>por</b> = through, by, because of, exchange; <b>para</b> = destination, purpose, deadline.',
    examples:[['Se tivesse tempo, ia contigo.','If I had time, I would go with you.'],['Obrigado por tudo.','Thank you for everything.'],['Este comboio é para o Porto.','This train is for Porto.']],
    qs:[
      { q:'"If I had money, I would travel" is:', opts:['Se tivesse dinheiro, viajaria','Se tinha dinheiro, viajava','Se tenho dinheiro, viajo','Se terei dinheiro, viajarei'], a:0, why:'Unreal condition: imperfect subjunctive + conditional.' },
      { q:'"Thanks for the help" uses:', opts:['por','para','de','em'], a:0, why:'por covers cause and exchange: obrigado pela ajuda.' },
      { q:'"This gift is for you" uses:', opts:['para','por','de','com'], a:0, why:'para marks the destination or recipient.' },
      { q:'"I passed through Lisbon" uses:', opts:['por','para','a','em'], a:0, why:'por = through / via: passei por Lisboa.' },
      { q:'"If you can, call me" is:', opts:['Se puderes, liga-me','Se podes, liga-me','Se poderias, liga-me','Se pudesses, liga-me'], a:0, why:'Real future condition uses the future subjunctive: se puderes.' },
      { q:'para also marks:', opts:['a deadline','a cause','an exchange','a route'], a:0, why:'para amanhã = by tomorrow; those others belong to por.' },
    ]},
  { id:'pt_past', unit:'pt-core-4', icon:'⏪', title:'The past: pretérito perfeito',
    explain:'For finished actions, use the <b>pretérito perfeito</b>. For <i>falar</i>: fal<b>ei</b>, fal<b>aste</b>, fal<b>ou</b>, fal<b>ámos</b>, fal<b>aram</b>. For <i>comer</i>: com<b>i</b>, com<b>este</b>, com<b>eu</b>, com<b>emos</b>, com<b>eram</b>. Two you will use daily: <i>fui</i> (I went / I was) and <i>tive</i> (I had).',
    examples:[['Ontem falei com a minha mãe.','Yesterday I spoke with my mother.'],['Comi peixe ao almoço.','I ate fish for lunch.'],['Fomos à praia no domingo.','We went to the beach on Sunday.']],
    qs:[
      { q:'"I spoke" is:', opts:['falei','falo','falarei','falava'], a:0, why:'-ar verbs take -ei for eu in the past.' },
      { q:'"He ate" is:', opts:['comeu','comi','come','comeram'], a:0, why:'-er verbs take -eu for ele/ela.' },
      { q:'"We went" is:', opts:['fomos','vamos','fui','foram'], a:0, why:'ir is irregular: fui, foste, foi, fomos, foram.' },
      { q:'"Yesterday I worked" is:', opts:['Ontem trabalhei','Ontem trabalho','Ontem vou trabalhar','Ontem trabalhar'], a:0, why:'Finished action + ontem → trabalhei.' },
      { q:'"They arrived" is:', opts:['chegaram','chegam','chegarão','chegando'], a:0, why:'eles → -aram for -ar verbs.' },
      { q:'"I had" (ter) is:', opts:['tive','tenho','terei','tinha'], a:0, why:'tive is the pretérito perfeito of ter.' },
    ]},
  { id:'pt_gs_discurso', unit:'pt-core-13', icon:'🧵', title:'Coesão e discurso (C1)',
    explain:'A C1 o difícil deixa de ser a frase e passa a ser o <b>texto</b>. Três instrumentos fazem quase todo o trabalho. <b>1. Referência</b> — em vez de repetir o nome, aponte para ele: <b>isso</b>, <b>esse problema</b>, <b>tal medida</b>, <b>o mesmo</b>. <b>2. Sinalização</b> — diga ao leitor que movimento se segue: <b>Em primeiro lugar… Além disso… Por outro lado… Por conseguinte…</b> <b>3. Concessão</b> — nomeie a posição contrária antes de responder: <b>É verdade que… No entanto…</b> / <b>Há quem defenda que… Têm razão num ponto, mas…</b> Um texto C1 não enumera opiniões; move-se entre elas.',
    examples:[
      ['O problema não é a mudança. O problema é quem decide a mudança.','Repetir a palavra-chave de propósito e depois torcê-la — contraste forte.'],
      ['É verdade que o turismo traz emprego. No entanto, esse emprego desaparece quando o hotel fecha.','Conceder e depois responder: o movimento central do C1.'],
      ['Em primeiro lugar, há um custo. Além disso, há algo que não aparece nas contas.','Sinalização: o leitor sabe que vem um segundo argumento.'],
    ],
    qs:[
      { q:'Qual destas aberturas concede antes de discordar?', opts:['É verdade que… no entanto…','Em primeiro lugar…','Por conseguinte…','Eu acho que…'], a:0, why:'"É verdade que… no entanto…" nomeia a posição contrária e depois responde-lhe.' },
      { q:'Em vez de repetir "esse problema da água" três vezes, pode escrever…', opts:['isso','outro','tudo','assim'], a:0, why:'As palavras de referência apontam para trás sem repetir a expressão inteira.' },
      { q:'Que conector introduz uma consequência?', opts:['Por conseguinte','Além disso','Por outro lado','Como'], a:0, why:'Por conseguinte = consequentemente. Além disso acrescenta; por outro lado contrasta.' },
      { q:'Um parágrafo C1 é fraco sobretudo quando…', opts:['Enumera opiniões sem se mover entre elas','Usa palavras longas','Tem frases curtas','Dá exemplos'], a:0, why:'O movimento — concessão, consequência, ressalva — é o que marca a escrita C1.' },
      { q:'"Há quem defenda que…" serve para…', opts:['Introduzir uma posição a que vai responder','Dar a sua própria opinião','Terminar um texto','Fazer uma pergunta'], a:0, why:'Serve para apresentar a posição contrária e poder respondê-la.' },
      { q:'Qual é a melhor forma de concluir sem repetir a introdução?', opts:['Retirar uma implicação que o leitor ainda não viu','Repetir a sua posição','Resumir cada parágrafo','Pedir desculpa pela extensão'], a:0, why:'As conclusões C1 estendem o argumento em vez de o repetirem.' },
    ] },
];

const PT_GRAMMAR_SPOTLIGHTS = {
  pt_greetings:     { title:'obrigado / obrigada', explain:'"Thank you" agrees with <b>the speaker</b>, not the listener. A man always says <b>obrigado</b>; a woman always says <b>obrigada</b>.', examples:[['Obrigado! (man speaking)','Thank you!'],['Obrigada! (woman speaking)','Thank you!'],['Muito obrigada pela ajuda.','Thank you very much for the help.']] },
  pt_introductions: { title:'Chamo-me… (reflexive verbs)', explain:'To give your name, Portuguese uses a reflexive: <b>chamo-me</b> = literally "I call myself". In Portugal the pronoun hooks on after the verb with a hyphen.', examples:[['Chamo-me Ana.','My name is Ana.'],['Como se chama?','What is your name?'],['Levanto-me às sete.','I get up at seven.']] },
  pt_essentials:    { title:'não goes before the verb', explain:'To negate anything, put <b>não</b> straight before the verb. To answer "no", say <b>não</b> twice: once as the answer, once in the sentence.', examples:[['Não percebo.','I do not understand.'],['Não, não quero.','No, I do not want to.'],['Ele não está em casa.','He is not at home.']] },
  pt_numbers:       { title:'um/uma and dois/duas change', explain:'Only the numbers 1 and 2 change for gender: <b>um</b>/<b>uma</b>, <b>dois</b>/<b>duas</b>. Everything from three upwards stays the same.', examples:[['um café, uma água','one coffee, one water'],['dois irmãos, duas irmãs','two brothers, two sisters'],['três bilhetes','three tickets']] },
  pt_food:          { title:'Ordering politely', explain:'The standard restaurant formula is <b>Queria…</b> (I would like) or <b>Um … se faz favor</b>. <i>Queria</i> sounds softer than <i>quero</i>.', examples:[['Queria a ementa, se faz favor.','I would like the menu, please.'],['Um café, por favor.','A coffee, please.'],['A conta, se faz favor.','The bill, please.']] },
  pt_daily:         { title:'estar a + infinitive', explain:'European Portuguese says "I am doing" as <b>estar a</b> + infinitive: <i>Estou a comer</i>. (Brazil uses <i>estou comendo</i> — you will hear both, but use the first in Portugal and Cape Verde.)', examples:[['Estou a aprender português.','I am learning Portuguese.'],['Ela está a trabalhar.','She is working.'],['O que estás a fazer?','What are you doing?']] },
  pt_directions:    { title:'Polite commands', explain:'To give directions politely, use the <b>você</b> form: <i>vire</i> (turn), <i>siga</i> (continue), <i>atravesse</i> (cross). Add <b>se faz favor</b> to soften it further.', examples:[['Vire à direita.','Turn right.'],['Siga sempre em frente.','Keep going straight.'],['Atravesse a rua aqui.','Cross the street here.']] },
  pt_shopping:      { title:'Talking about price', explain:'<b>Quanto custa?</b> for one thing, <b>Quanto custam?</b> for several. To compare, use <b>mais … do que</b> / <b>menos … do que</b>.', examples:[['Quanto custa este?','How much does this cost?'],['É mais barato do que o outro.','It is cheaper than the other one.'],['Pode fazer um desconto?','Can you give a discount?']] },
  pt_colors:        { title:'Adjectives follow the noun', explain:'Unlike English, the colour comes AFTER the noun and copies its gender and number: <i>um carro branco</i>, <i>uma casa branca</i>, <i>duas casas brancas</i>.', examples:[['um carro branco','a white car'],['uma camisa branca','a white shirt'],['sapatos pretos','black shoes']] },
  pt_body:          { title:'The body takes "o/a", not "meu"', explain:'With body parts Portuguese uses the article, not the possessive: <i>Dói-me <b>a</b> cabeça</i> — literally "the head hurts me". Saying "a minha cabeça dói" sounds foreign.', examples:[['Lavo as mãos.','I wash my hands.'],['Dói-me o braço.','My arm hurts.'],['Cortei o dedo.','I cut my finger.']] },
  pt_house:         { title:'em + article = no / na', explain:'"In the" contracts: em + o = <b>no</b>, em + a = <b>na</b>. So <i>na cozinha</i>, <i>no quarto</i> — never "em a cozinha".', examples:[['Estou na cozinha.','I am in the kitchen.'],['O livro está no quarto.','The book is in the bedroom.']] },
  pt_weather:       { title:'Weather uses estar and fazer', explain:'Portuguese says <b>está</b> + adjective (<i>está calor</i>) or <b>faz</b> + noun (<i>faz frio</i>). Both are correct; <i>está</i> is more common in Portugal for right now.', examples:[['Está a chover.','It is raining.'],['Faz frio no inverno.','It is cold in winter.'],['Está muito vento.','It is very windy.']] },
  pt_animals:       { title:'Plurals ending in -ão', explain:'Many animal and everyday words end in -ão and pluralise in three ways: <b>-ões</b> (leão→leões), <b>-ães</b> (cão→cães), <b>-ãos</b> (irmão→irmãos). Learn each one with its plural.', examples:[['cão → cães','dog → dogs'],['leão → leões','lion → lions'],['irmão → irmãos','brother → brothers']] },
  pt_clothing:      { title:'vestir, calçar, pôr', explain:'Portuguese picks a different verb by body zone: <b>vestir</b> for clothes, <b>calçar</b> for shoes and socks, <b>pôr</b> for hats and glasses.', examples:[['Vou vestir o casaco.','I am going to put on the coat.'],['Calço os sapatos.','I put on my shoes.'],['Põe o chapéu.','Put on the hat.']] },
  pt_emotions:      { title:'ser vs estar with feelings', explain:'<b>Estar</b> + adjective = how you feel now (<i>estou triste</i>). <b>Ser</b> + adjective = what you are like always (<i>ele é triste</i> = he is a sad person). Getting this wrong changes the meaning entirely.', examples:[['Estou nervoso.','I am nervous (right now).'],['Ele é nervoso.','He is a nervous person.'],['Estás cansada?','Are you tired?']] },
  pt_core_verbs:    { title:'saber vs conhecer', explain:'<b>Saber</b> = to know a fact or how to do something. <b>Conhecer</b> = to be acquainted with a person, place or work.', examples:[['Sei nadar.','I know how to swim.'],['Não sei a resposta.','I do not know the answer.'],['Conheço o teu irmão.','I know your brother.']] },
  pt_questions:     { title:'The "é que" trick', explain:'Everyday spoken questions slip <b>é que</b> after the question word — it changes nothing in meaning but sounds far more natural: <i>Onde é que moras?</i>', examples:[['O que é que fazes?','What do you do?'],['Porque é que não vieste?','Why did you not come?'],['Quando é que chegas?','When do you arrive?']] },
  pt_money:         { title:'Numbers with money', explain:'Prices are said with <b>e</b> between units: <i>dois euros e cinquenta</i>. And remember <b>custar</b> (to cost) agrees: <i>custa</i> for one, <i>custam</i> for several.', examples:[['Custa três euros e vinte.','It costs three euros twenty.'],['Quanto custam estes?','How much do these cost?']] },
  pt_idioms:        { title:'Softening words', explain:'European Portuguese softens almost everything with small words: <b>se calhar</b> (maybe), <b>lá</b>, <b>então</b>, and the ever-present <b>pois</b>. Using them makes you sound local faster than any grammar rule.', examples:[['Se calhar tens razão.','Maybe you are right.'],['Pois é…','Yeah, that is how it is…'],['Então, vamos?','So, shall we go?']] },
  pt_formal:        { title:'você, o senhor, or nothing', explain:'For formal address, Portugal often avoids the pronoun entirely and uses the title plus third person: <i>O senhor deseja alguma coisa?</i> Using <b>tu</b> with a stranger can sound rude.', examples:[['O senhor precisa de ajuda?','Do you need help, sir?'],['A dona Maria já chegou?','Has Mrs Maria arrived?'],['Queira sentar-se.','Please take a seat.']] },
  pt_academic:      { title:'Register: contudo, não mas', explain:'Formal Portuguese swaps everyday connectors for heavier ones: <b>mas</b>→<b>contudo/todavia</b>, <b>por isso</b>→<b>por conseguinte</b>, <b>sobre</b>→<b>no que diz respeito a</b>. Using them signals an academic or professional register.', examples:[['Contudo, os dados são limitados.','However, the data are limited.'],['Por conseguinte, propomos uma revisão.','Consequently, we propose a revision.']] },
  pt_nuance:        { title:'Softening a disagreement', explain:'Direct contradiction is rare in Portuguese. Speakers wrap disagreement: <i>Com todo o respeito…</i>, <i>Concordo até certo ponto, mas…</i>, <i>Não deixa de ser verdade que…</i>. The softer the wrapper, the stronger the point can be.', examples:[['Concordo até certo ponto.','I agree up to a point.'],['Com todo o respeito, discordo.','With all due respect, I disagree.']] },
  pt_expressions2:  { title:'Reading a proverb', explain:'Proverbs are fixed — you cannot change the words. Learn them whole and drop them in at the end of a point, which is where speakers place them.', examples:[['Devagar se vai ao longe.','Slow and steady goes far.'],['Quem não arrisca não petisca.','Nothing ventured, nothing gained.']] },
  pt_health:        { title:'Dói-me… (saying what hurts)', explain:'Portuguese says the pain does the acting: <b>dói-me a cabeça</b> = "the head hurts me". Use <b>dói-me</b> for one thing and <b>doem-me</b> for several.', examples:[['Dói-me a cabeça.','I have a headache.'],['Doem-me as costas.','My back hurts.'],['Sinto-me mal.','I feel unwell.']] },
};

const PT_SENTENCE_PATTERNS = {
  alphabet: [
    { pattern:'Nasal sounds: ã, õ, ão', en:'Let the air go through the nose. "ão" is the signature Portuguese sound — pão, não, coração.',
      examples:[['pão / não','bread / no'],['irmã / limões','sister / lemons']] },
    { pattern:'lh and nh', en:'Two letters, one sound: lh = "ly" (filho), nh = "ny" (senhora).',
      examples:[['filho, olho, trabalho','son, eye, work'],['senhora, dinheiro, manhã','madam, money, morning']] },
    { pattern:'s changes with position', en:'"s" is s at the start, z between vowels, and sh at the end of a word.',
      examples:[['sol → "s"','sun'],['casa → "z"','house'],['dois → "sh"','two']] },
  ],
  pt_greetings: [
    { pattern:'Bom dia / Boa tarde / Boa noite', en:'The greeting agrees with the noun: dia is masculine (bom), tarde and noite are feminine (boa).',
      examples:[['Bom dia!','Good morning!'],['Boa tarde!','Good afternoon!']] },
    { pattern:'Como está? vs Como estás?', en:'está is polite or for someone older; estás is for friends and family.',
      examples:[['Como está, senhor Silva?','How are you, Mr Silva?'],['Olá Ana, como estás?','Hi Ana, how are you?']] },
  ],
  pt_introductions: [
    { pattern:'Sou / Sou de / Tenho … anos', en:'Three sentences cover most introductions: who you are, where you are from, how old you are.',
      examples:[['Sou enfermeira.','I am a nurse.'],['Sou de Cabo Verde.','I am from Cape Verde.'],['Tenho trinta anos.','I am thirty.']] },
    { pattern:'Age uses ter, not ser', en:'Portuguese "has" years rather than "is" years old.',
      examples:[['Tenho vinte anos.','I am twenty.'],['Quantos anos tens?','How old are you?']] },
  ],
  pt_time: [
    { pattern:'São … horas / É uma hora', en:'Use são for every hour except one o\'clock, which takes é.',
      examples:[['São três horas.','It is three o\'clock.'],['É uma hora.','It is one o\'clock.']] },
    { pattern:'às + hour', en:'To say "at" a time, use às (or à uma).',
      examples:[['Chego às oito.','I arrive at eight.'],['A aula é à uma.','The class is at one.']] },
  ],
  pt_food: [
    { pattern:'Queria… (the polite order)', en:'Queria is the softest way to order anything.',
      examples:[['Queria um café.','I would like a coffee.'],['Queria a conta, se faz favor.','I would like the bill, please.']] },
  ],
  pt_directions: [
    { pattern:'Onde fica…?', en:'The standard way to ask where something is.',
      examples:[['Onde fica a estação?','Where is the station?'],['Onde fica a casa de banho?','Where is the bathroom?']] },
  ],
};

